using Microsoft.AspNetCore.Mvc;
using RaceDay.Mvc.Models;
using RaceDay.Mvc.Services;
namespace RaceDay.Mvc.Controllers;
public class OrganiserController(ApiClient api):BaseController
{
 public async Task<IActionResult> Index(){var g=Guard("Organiser");if(g!=null)return g;var r=await api.Get("api/events");ViewBag.Events=r.Data;ViewBag.Error=r.Error;return View();}
 public async Task<IActionResult> Events(){var g=Guard("Organiser");if(g!=null)return g;var r=await api.Get("api/events");ViewBag.Events=r.Data;ViewBag.Error=r.Error;return View();}
 public IActionResult CreateEvent(){var g=Guard("Organiser");if(g!=null)return g;return View(new EventVm());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> CreateEvent(EventVm vm){if(!ModelState.IsValid)return View(vm);var r=await api.Post("api/events",new{vm.Name,vm.Description,vm.Location,vm.EventDate});if(!r.Ok){ModelState.AddModelError("",r.Error??"Unable to create event.");return View(vm);}TempData["Success"]="Event created.";return RedirectToAction("Events");}
 public async Task<IActionResult> EditEvent(int id){var g=Guard("Organiser");if(g!=null)return g;var r=await api.Get($"api/events/{id}");if(!r.Ok)return RedirectToAction("Events");var e=r.Data;return View(new EventVm{EventId=id,Name=e.GetProperty("name").GetString()??"",Description=e.TryGetProperty("description",out var d)?d.GetString():"",Location=e.GetProperty("location").GetString()??"",EventDate=e.GetProperty("eventDate").GetDateTime()});}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> EditEvent(EventVm vm){if(!ModelState.IsValid)return View(vm);var r=await api.Put($"api/events/{vm.EventId}",new{vm.Name,vm.Description,vm.Location,vm.EventDate});if(!r.Ok)ModelState.AddModelError("",r.Error??"Update failed.");else TempData["Success"]="Event updated.";return View(vm);}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> DeleteEvent(int id){var g=Guard("Organiser");if(g!=null)return g;var r=await api.Delete($"api/events/{id}");TempData[r.Ok?"Success":"Error"]=r.Ok?"Event deleted.":r.Error;return RedirectToAction("Events");}
 public async Task<IActionResult> Categories(int id){var g=Guard("Organiser");if(g!=null)return g;ViewBag.EventId=id;var e=await api.Get($"api/events/{id}");ViewBag.EventName=e.Data.TryGetProperty("name",out var n)?n.GetString():"Event";var r=await api.Get($"api/events/{id}/categories");ViewBag.Categories=r.Data;ViewBag.Error=r.Error;return View(new CategoryVm());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> AddCategory(int id,CategoryVm vm){if(!ModelState.IsValid)return RedirectToAction("Categories",new{id});var r=await api.Post($"api/events/{id}/categories",new{vm.Name,vm.DistanceKm,vm.MaxParticipants});TempData[r.Ok?"Success":"Error"]=r.Ok?"Category added.":r.Error;return RedirectToAction("Categories",new{id});}
 public async Task<IActionResult> Enrolments(int id){var g=Guard("Organiser");if(g!=null)return g;var e=await api.Get($"api/events/{id}");ViewBag.EventName=e.Data.TryGetProperty("name",out var n)?n.GetString():"Event";ViewBag.EventId=id;var r=await api.Get($"api/events/{id}/enrolments");ViewBag.Items=r.Data;ViewBag.Error=r.Error;return View();}
 public async Task<IActionResult> Results(int id){var g=Guard("Organiser");if(g!=null)return g;ViewBag.EventId=id;var e=await api.Get($"api/events/{id}");ViewBag.EventName=e.Data.TryGetProperty("name",out var n)?n.GetString():"Event";var a=await api.Get($"api/events/{id}/enrolments");ViewBag.Enrolments=a.Data;var r=await api.Get($"api/events/{id}/results");ViewBag.Results=r.Data;ViewBag.Error=r.Error;return View(new ResultVm());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SaveResult(int eventId,int enrolmentId,ResultVm vm){if(!ModelState.IsValid)return RedirectToAction("Results",new{id=eventId});if(!TimeSpan.TryParse(vm.FinishTime,out var t)){TempData["Error"]="Enter finish time as HH:MM:SS.";return RedirectToAction("Results",new{id=eventId});}var r=await api.Post($"api/enrolments/{enrolmentId}/result",new{finishTime=t.ToString(),vm.Position});TempData[r.Ok?"Success":"Error"]=r.Ok?"Result published.":r.Error;return RedirectToAction("Results",new{id=eventId});}
}
